import 'package:firebase_auth/firebase_auth.dart';import 'package:flutter/material.dart';import 'package:geolocator/geolocator.dart';import 'package:shared_preferences/shared_preferences.dart';import '../services/services.dart';
class ProfilePage extends StatefulWidget{const ProfilePage({super.key,required this.onMode,required this.onSeed});final ValueChanged<ThemeMode> onMode;final ValueChanged<Color> onSeed;@override State<ProfilePage> createState()=>_S();}
class _S extends State<ProfilePage>{String home='Not marked',contact='Not configured';Future<void> mark()async{var p=await Geolocator.checkPermission();if(p==LocationPermission.denied)p=await Geolocator.requestPermission();if(p==LocationPermission.denied||p==LocationPermission.deniedForever)return;final x=await Geolocator.getCurrentPosition();final s=await SharedPreferences.getInstance();await s.setDouble('homeLat',x.latitude);await s.setDouble('homeLng',x.longitude);setState(()=>home='${x.latitude.toStringAsFixed(4)}, ${x.longitude.toStringAsFixed(4)}');}Future<void> trusted()async{final x=TextEditingController();await showDialog(context:context,builder:(c)=>AlertDialog(title:const Text('Trusted contact'),content:TextField(controller:x,keyboardType:TextInputType.phone,decoration:const InputDecoration(labelText:'Phone number')),actions:[FilledButton(onPressed:()async{final s=await SharedPreferences.getInstance();await s.setString('trusted',x.text.trim());if(c.mounted)Navigator.pop(c);setState(()=>contact=x.text.trim());},child:const Text('Save'))]));}@override Widget build(BuildContext c){final u=FirebaseAuth.instance.currentUser!;return ListView(padding:const EdgeInsets.fromLTRB(18,18,18,100),children:[const Text('Profile & Studio',style:TextStyle(fontSize:27,fontWeight:FontWeight.w900)),const SizedBox(height:14),Card(child:ListTile(contentPadding:const EdgeInsets.all(16),leading:const CircleAvatar(radius:28,child:Icon(Icons.person,size:30)),title:Text(u.displayName??'WATCHKEEPER user',style:const TextStyle(fontWeight:FontWeight.w900,fontSize:18)),subtitle:Text(u.email??''))),const SizedBox(height:10),Card(child:Column(children:[ListTile(leading:const Icon(Icons.home_work_outlined),title:const Text('Mark Home safe zone'),subtitle:Text(home),onTap:mark),ListTile(leading:const Icon(Icons.health_and_safety_outlined),title:const Text('Trusted contact'),subtitle:Text(contact),onTap:trusted),ListTile(leading:const Icon(Icons.notifications_active_outlined),title:const Text('Test notification'),onTap:Alerts.i.test)])),const SizedBox(height:10),Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Appearance',style:TextStyle(fontSize:19,fontWeight:FontWeight.w900)),const SizedBox(height:8),Wrap(spacing:7,children:[ActionChip(label:const Text('Auto'),onPressed:()=>widget.onMode(ThemeMode.system)),ActionChip(label:const Text('Light'),onPressed:()=>widget.onMode(ThemeMode.light)),ActionChip(label:const Text('Midnight'),onPressed:()=>widget.onMode(ThemeMode.dark))]),const SizedBox(height:12),Wrap(spacing:10,children:[const Color(0xFF7C5CFF),const Color(0xFF00A8E8),const Color(0xFF00A86B),const Color(0xFFFF6A2A),const Color(0xFFE63E8C)].map((x)=>InkWell(onTap:()=>widget.onSeed(x),child:Container(width:42,height:42,decoration:BoxDecoration(color:x,shape:BoxShape.circle,boxShadow:[BoxShadow(color:x.withValues(alpha:.35),blurRadius:14)]))).toList())]))),const SizedBox(height:10),Card(child:ListTile(leading:const Icon(Icons.logout),title:const Text('Sign out'),onTap:FirebaseAuth.instance.signOut))]);}}
